1	import { Block, Text } from "@prototyp/skeletor";
2	import {
3	  EmbeddedEventDetails_Tags,
4	  type EventTimelineItem,
5	  type MediaSourceInterface,
6	  MessageLikeEventContent_Tags,
7	  MessageType_Tags,
8	  MsgLikeKind_Tags,
9	  ProfileDetails_Tags,
10	  TimelineEventType_Tags,
11	  TimelineItemContent_Tags,
12	} from "@unomed/react-native-matrix-sdk";
13	import { useSetAtom } from "jotai";
14	import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
15	import {
16	  cleanMentions,
17	  getEventTextContent,
18	  getMessageTextContent,
19	} from "modules/matrix-client/utils";
20	import { TimelineAtoms } from "modules/timeline/jotai";
21	import { TimelineService } from "modules/timeline/service/TimelineService";
22	import { type FC, useCallback, useEffect, useMemo, useState } from "react";
23	import { Dimensions, Image, StyleSheet } from "react-native";
24	import { MessageTimestamp, PinIndicator, SeenBy } from "shared/components";
25	import { Colors, TextSize } from "shared/styles";
26	import { MentionText } from "../mention-text";
27	import { MessageLongPressWrapper } from "../message-long-press-wrapper";
28	import { MessageReactionsOverlay } from "../message-reactions-overlay";
29	import { MessageSender } from "../message-sender";
30	import { ReplyPayload } from "../reply-paylaod";
31	
32	interface Props {
33	  roomId: string;
34	  event: EventTimelineItem;
35	  isPreviousSameSender: boolean;
36	  onMemberPress?: (member: MemberDetailsPayload) => void;
37	}
