39	const MAX_WIDTH = Dimensions.get("window").width - 60;
40	
41	// Parse <a href="https://matrix.to/#/@user:server">@DisplayName</a> tags from
42	// formatted_body HTML into a lowercase-displayName → userId map.
43	// This is the sync fast path — no profile loading needed.
44	const parseMentionMapFromHtml = (html: string): Map<string, string> => {
45	  const regex =
46	    /<a[^>]+href="https:\/\/matrix\.to\/#\/(@[^"]+)"[^>]*>@?([^<]+)<\/a>/gi;
47	  const matches = Array.from(html.matchAll(regex));
48	  return new Map(matches.map((m) => [m[2].toLowerCase(), m[1]]));
49	};
50	
51	export const TextMessage: FC<Props> = ({
52	  roomId,
53	  event,
54	  isPreviousSameSender,
55	  onMemberPress,
56	}) => {
57	  const [messageWidth, setMessageWidth] = useState(116);
58	  const isUser = event.isOwn;
59	  const sender = event.senderProfile;
60	  const senderId = event.sender;
61	  const seenByUsers = TimelineService.getReadReceiptUsers(event);
62	  const [fetchedReplyPayload, setFetchedReplyPayload] =
63	    useState<TimelineReplyPayload | null>(null);
64	  const [mentionMap, setMentionMap] = useState<Map<string, string>>(new Map());
65	  // Some clients (Element X) put raw markdown links in the body:
66	  // [@Name](matrix.to/#/@user:server)  — link text has @
67	  // [Name](matrix.to/#/@user:server)   — link text without @
68	  // Detect by the /#/@ pattern in the URL (user permalink) and normalize to @Name.
69	  const content = cleanMentions(getEventTextContent(event));
70	  const setScrollToEventId = useSetAtom(TimelineAtoms.scrollToEventId);
71	
72	  const { formattedBody, mentionUserIds, isEdited } = useMemo(() => {
73	    if (event.content.tag !== TimelineItemContent_Tags.MsgLike) {
74	      return { formattedBody: undefined, mentionUserIds: [], isEdited: false };
75	    }
76	    const kind = event.content.inner.content.kind;
77	    if (kind?.tag !== MsgLikeKind_Tags.Message) {
78	      return { formattedBody: undefined, mentionUserIds: [], isEdited: false };
79	    }
80	    const msgType = kind.inner.content.msgType;
81	    const html =
82	      msgType?.tag === MessageType_Tags.Text
83	        ? msgType.inner.content.formatted?.body
84	        : undefined;
85	    return {
86	      formattedBody: html,
87	      mentionUserIds: kind.inner.content.mentions?.userIds ?? [],
88	      isEdited: kind.inner.content.isEdited,
89	    };
90	  }, [event]);
91	
92	  const replyPayload = useMemo(() => {
93	    if (event.content.tag !== TimelineItemContent_Tags.MsgLike) return null;
94	
95	    const inReplyTo = event.content.inner.content.inReplyTo;
96	
97	    if (!inReplyTo) return null;
98	
99	    const eventDetails = inReplyTo.event();
100	
101	    if (eventDetails.tag === EmbeddedEventDetails_Tags.Unavailable) {
102	      return {
103	        eventId: inReplyTo.eventId(),
104	        senderName: "",
105	        content: "",
106	        isUnavailable: true,
107	      };
108	    }
109	
110	    if (eventDetails.tag !== EmbeddedEventDetails_Tags.Ready) return null;
111	
112	    const senderName =
113	      eventDetails.inner.senderProfile.tag === ProfileDetails_Tags.Ready
114	        ? (eventDetails.inner.senderProfile.inner.displayName ??
115	          eventDetails.inner.sender)
116	        : eventDetails.inner.sender;
117	
118	    let mediaSource: { source: MediaSourceInterface; mimetype: string } | null =
119	      null;
120	    const replyContent = eventDetails.inner.content;
121	
122	    if (replyContent.tag === TimelineItemContent_Tags.MsgLike) {
123	      const kind = replyContent.inner.content.kind;
124	      if (kind?.tag === MsgLikeKind_Tags.Message) {
125	        const msgType = kind.inner.content.msgType;
126	        if (msgType?.tag === MessageType_Tags.Image) {
127	          mediaSource = {
128	            source: msgType.inner.content.source,
129	            mimetype: msgType.inner.content.info?.mimetype || "image/jpeg",
130	          };
131	        }
132	        if (msgType?.tag === MessageType_Tags.Video) {
133	          mediaSource = {
134	            source: msgType.inner.content.source,
135	            mimetype: msgType.inner.content.info?.mimetype || "video/mp4",
136	          };
137	        }
138	      }
139	    }
140	
141	    return {
142	      eventId: inReplyTo.eventId(),
143	      senderName,
144	      content: getMessageTextContent(eventDetails.inner.content),
145	      mediaSource,
146	    };
147	  }, [event]);
148	
149	  const handleReplyPress = useCallback(() => {
150	    if (replyPayload) setScrollToEventId(replyPayload.eventId);
151	  }, [replyPayload, setScrollToEventId]);
152	
153	  useEffect(() => {
154	    if (!replyPayload?.isUnavailable) {
155	      setFetchedReplyPayload(null);
156	      return;
157	    }
158	
159	    const room = MatrixCore.getRoom(roomId);
160	    const client = MatrixCore.getClient();
161	
162	    room
163	      .loadOrFetchEvent(replyPayload.eventId)
164	      .then(async (fetchedEvent) => {
165	        const senderId = fetchedEvent.senderId();
166	
167	        let senderName = senderId;
168	        let mediaSource: {
169	          source: MediaSourceInterface;
170	          mimetype: string;
171	        } | null = null;
172	        try {
173	          const profile = await client.getProfile(senderId);
174	          senderName = profile.displayName ?? senderId;
175	        } catch {}
176	
177	        const eventType = fetchedEvent.eventType();
178	        let content = "";
179	        if (eventType.tag === TimelineEventType_Tags.MessageLike) {
180	          const msgContent = eventType.inner.content;
181	          if (msgContent.tag === MessageLikeEventContent_Tags.RoomMessage) {
182	            const msgType = msgContent.inner.messageType;
183	            if (msgType.tag === MessageType_Tags.Text) {
184	              content = msgType.inner.content.body;
185	            } else if (
186	              msgType.tag === MessageType_Tags.Audio ||
187	              msgType.tag === MessageType_Tags.File
188	            ) {
189	              content = msgType.inner.content.filename;
190	            } else if (
191	              msgType.tag === MessageType_Tags.Image ||
192	              msgType.tag === MessageType_Tags.Video
193	            ) {
194	              mediaSource = {
195	                source: msgType.inner.content.source,
196	                mimetype: msgType.inner.content.info?.mimetype || "image/jpeg",
197	              };
198	              content = msgType.inner.content.filename;
199	            }
200	          }
201	        }
202	
203	        setFetchedReplyPayload({
204	          eventId: replyPayload.eventId,
205	          senderName,
206	          content,
207	          mediaSource,
208	        });
209	      })
210	      .catch();
211	  }, [replyPayload?.isUnavailable, replyPayload?.eventId, roomId, event]);
212	
213	  useEffect(() => {
214	    // Fast path: extract mention map directly from formatted_body HTML
215	    if (formattedBody) {
216	      const map = parseMentionMapFromHtml(formattedBody);
217	      if (map.size > 0) {
218	        setMentionMap(map);
219	        return;
