70	/// A light wrapper around event timeline items returned from Rust.
71	class EventTimelineItemProxy {
72	    let item: MatrixRustSDK.EventTimelineItem
73	    let id: TimelineItemIdentifier
74	    
75	    init(item: MatrixRustSDK.EventTimelineItem, uniqueID: TimelineItemIdentifier.UniqueID) {
76	        self.item = item
77	        
78	        id = .event(uniqueID: uniqueID, eventOrTransactionID: .init(rustValue: item.eventOrTransactionId))
79	    }
80	    
81	    lazy var deliveryStatus: TimelineItemDeliveryStatus? = {
82	        guard let localSendState = item.localSendState else {
83	            return nil
84	        }
85	        
86	        switch localSendState {
87	        case .sendingFailed(let error, let isRecoverable):
88	            switch error {
89	            case .identityViolations(let users):
90	                return .sendingFailed(.verifiedUser(.changedIdentity(users: users)))
91	            case .insecureDevices(let userDeviceMap):
92	                return .sendingFailed(.verifiedUser(.hasUnsignedDevice(devices: userDeviceMap)))
93	            default:
94	                return .sendingFailed(.unknown)
95	            }
96	        case .notSentYet:
97	            return .sending
98	        case .sent:
99	            return .sent
